+    fn arb_types() -> impl Strategy<Value = Vec<&'static str>> {
+        (prop::collection::vec(arb_type(), 0..=3), 0usize..=3).prop_map(|(mut types, at)| {
+            let at = at.min(types.len());
+            types.insert(at, "string");
+            types
+        })
+    }
+
