+        prop_oneof![
+            Just("null".to_string()),
+            Just("NULL".to_string()),
+            Just("42".to_string()),
+            Just("-7".to_string()),
+            Just("0".to_string()),
+            Just("1".to_string()),
+            Just("3.5".to_string()),
+            Just("-0.25".to_string()),
+            Just("true".to_string()),
+            Just("false".to_string()),
+            Just("1e999".to_string()),
